def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = local + "@gmail.com"

        return value

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return (
            bool(local)
            and "." in domain
            and not domain.startswith(".")
            and not domain.endswith(".")
        )

    def normalize_phone(value):
        marker = re.search(r"ext|x|#", value, flags=re.IGNORECASE)
        if marker:
            value = value[:marker.start()]

        digits = "".join(ch for ch in value if ch.isdigit())
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) == 10 and digits[0] not in {"0", "1"}:
            return digits
        return ""

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    normalized = []

    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        if not valid_email(email):
            email = ""

        phone = normalize_phone(row["phone"])

        # Drop rows with neither a valid email nor a valid phone.
        if not email and not phone:
            continue

        tags = {
            tag.strip().lower()
            for tag in re.split(r"[;,]", row["tags"])
            if tag.strip()
        }

        normalized.append({
            "index": index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "tags": tags,
            "opted_out": is_opted_out(row["opted_out"]),
            "updated_dt": parse_updated(row["updated"]),
            "source": row["source"].strip().lower(),
        })

    count = len(normalized)
    parent = list(range(count))
    rank = [0] * count

    def find(item):
        while parent[item] != item:
            parent[item] = parent[parent[item]]
            item = parent[item]
        return item

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return

        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root

        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1

    by_email = {}
    by_phone_and_last_name = {}

    for i, row in enumerate(normalized):
        if row["email"]:
            previous = by_email.get(row["email"])
            if previous is None:
                by_email[row["email"]] = i
            else:
                union(i, previous)

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            previous = by_phone_and_last_name.get(key)
            if previous is None:
                by_phone_and_last_name[key] = i
            else:
                union(i, previous)

    groups = {}
    for i, row in enumerate(normalized):
        groups.setdefault(find(i), []).append(row)

    def preferred_value(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""

        best = max(
            candidates,
            key=lambda row: (
                row["source"] == "manual",
                row["updated_dt"],
                -row["index"],
            ),
        )
        return best[field]

    results = []

    for group in groups.values():
        all_tags = set()
        for row in group:
            all_tags.update(row["tags"])

        latest = max(row["updated_dt"] for row in group)

        results.append({
            "first_name": preferred_value(group, "first_name"),
            "last_name": preferred_value(group, "last_name"),
            "zip": preferred_value(group, "zip"),
            "email": preferred_value(group, "email"),
            "phone": preferred_value(group, "phone"),
            "source": preferred_value(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": (
                "Y" if any(row["opted_out"] for row in group) else "N"
            ),
            "updated": latest.strftime("%Y-%m-%d"),
            "_earliest_index": min(row["index"] for row in group),
        })

    results.sort(key=lambda person: person["_earliest_index"])

    for person in results:
        del person["_earliest_index"]

    return results
